// src/webview/ui/components/SearchInput.tsx
import { useState, useEffect } from "preact/hooks";

interface Props {
  query: string;
  onSearch: (query: string) => void;
  onClear: () => void;
}

export function SearchInput({ query, onSearch, onClear }: Props) {
  const [local, setLocal] = useState(query);

  // Sync external query changes (e.g. cleared by host)
  useEffect(() => { setLocal(query); }, [query]);

  // Debounce search → host
  useEffect(() => {
    const t = setTimeout(() => {
      if (local) {
        onSearch(local);
      } else {
        onClear();
      }
    }, 250);
    return () => clearTimeout(t);
  }, [local]);

  return (
    <div style="position:relative;flex:2;min-width:120px;">
      <input
        class="toolbar__search"
        type="search"
        placeholder="Search conversations…"
        value={local}
        onInput={(e) => setLocal((e.target as HTMLInputElement).value)}
        style="width:100%"
      />
      {local && (
        <button
          onClick={() => { setLocal(""); onClear(); }}
          style={{
            position: "absolute",
            right: 4,
            top: "50%",
            transform: "translateY(-50%)",
            background: "none",
            border: "none",
            cursor: "pointer",
            color: "var(--vscode-foreground)",
            fontSize: 12,
          }}
          class="codicon codicon-close"
        />
      )}
    </div>
  );
}
